(()=>{
const board=document.querySelector('#board'),roster=document.querySelector('#roster'),details=document.querySelector('#details'),message=document.querySelector('#message'),saved=document.querySelector('#saved');
const key='ember-formation-v1',rows=8,cols=7;
const defaults=[{id:'a1',name:'盾衛一',job:'盾衛',type:0,range:1,r:4,c:2},{id:'a2',name:'盾衛二',job:'盾衛',type:0,range:1,r:4,c:4},{id:'a3',name:'雙劍',job:'近戰',type:1,range:1,r:5,c:3},{id:'a4',name:'燼羽',job:'法師',type:2,range:3,r:7,c:2},{id:'a5',name:'火法二',job:'法師',type:2,range:3,r:7,c:4}];
const enemies=[{name:'魔像一',r:1,c:1},{name:'魔像二',r:1,c:3},{name:'魔像三',r:1,c:5},{name:'魔像四',r:2,c:2},{name:'魔像五',r:2,c:4}];
let units=structuredClone(defaults),selected=null,history=[],partyReady=false,enemyReady=false;
function valid(data){if(!Array.isArray(data)||data.length!==5)return false;const ids=new Set(),positions=new Set();return data.every(p=>{if(!p||!defaults.some(d=>d.id===p.id)||!Number.isInteger(p.r)||!Number.isInteger(p.c)||p.r<4||p.r>=8||p.c<0||p.c>=7||ids.has(p.id)||positions.has(p.r+','+p.c))return false;ids.add(p.id);positions.add(p.r+','+p.c);return true})}
try{const data=JSON.parse(localStorage.getItem(key));if(valid(data)){units=defaults.map(d=>{const p=data.find(p=>p.id===d.id);return {...d,r:p.r,c:p.c}});saved.textContent='已讀取本機陣形'}}catch{}
const party=new Image(),golem=new Image();party.onload=()=>{partyReady=true;paintSprites()};party.src='assets/formation-party.png';golem.onload=()=>{enemyReady=true;paintSprites()};golem.src='assets/flame-sequence.png';
function save(){try{localStorage.setItem(key,JSON.stringify(units.map(({id,r,c})=>({id,r,c}))));saved.textContent='已儲存在此瀏覽器'}catch{saved.textContent='本次暫存（無法寫入）'}}
function remember(){history.push(structuredClone(units));if(history.length>20)history.shift()}
function hexDistance(a,b){const aq=a.c-(a.r-(a.r&1))/2,bq=b.c-(b.r-(b.r&1))/2,dq=aq-bq,dr=a.r-b.r;return (Math.abs(dq)+Math.abs(dr)+Math.abs(dq+dr))/2}
function say(text){message.textContent=text}
function select(id){selected=id;const u=units.find(p=>p.id===id);say('已選 '+u.name+'：點空格移動，或點隊友交換位置。');render()}
function onCell(r,c){const current=units.find(p=>p.id===selected),occupant=units.find(p=>p.r===r&&p.c===c);if(!current){if(occupant)select(occupant.id);else say(r<4?'上方為敵方與中立區，請先選取我方隊員。':'請先從隊伍或戰場選一位隊員。');return}if(r<4){say('此處不可部署。我方只能放在第5～8列。');return}if(occupant?.id===current.id){selected=null;say('已取消選取。');render();return}remember();if(occupant){const from={r:current.r,c:current.c};current.r=r;current.c=c;occupant.r=from.r;occupant.c=from.c;say(current.name+' 與 '+occupant.name+' 已交換位置。')}else{current.r=r;current.c=c;say(current.name+' 已移至第'+(r+1)+'列、第'+(c+1)+'欄。')}save();render()}
function sprite(parent,type,enemy=false){const node=document.createElement('div');node.className=parent.classList.contains('roster-unit')?'portrait':'actor';const canvas=document.createElement('canvas');canvas.width=128;canvas.height=156;canvas.dataset.type=type;canvas.dataset.enemy=enemy?'1':'0';node.append(canvas);parent.append(node)}
function paintSprites(){document.querySelectorAll('canvas[data-type]').forEach(c=>{const x=c.getContext('2d');x.clearRect(0,0,128,156);const enemy=c.dataset.enemy==='1';if(enemy){if(!enemyReady)return;const sw=golem.naturalWidth/4,sh=golem.naturalHeight/4;x.drawImage(golem,sw*.55,sh*.2,sw*.45,sh*.8,7,6,114,146)}else{if(!partyReady)return;const type=+c.dataset.type;const crops=[[0,.365],[.36,.335],[.682,.318]],p=crops[type],sx=party.naturalWidth*p[0],w=party.naturalWidth*p[1],h=party.naturalHeight;const scale=Math.min(128/w,156/h),dw=w*scale,dh=h*scale;x.drawImage(party,sx,0,w,h,(128-dw)/2,156-dh,dw,dh)}})}
function render(){const focused=document.activeElement,focusCell=focused?.classList.contains('hex')?{r:focused.dataset.row,c:focused.dataset.col}:null,focusRoster=focused?.classList.contains('roster-unit')?focused.getAttribute('aria-label'):null;const u=units.find(p=>p.id===selected);board.querySelectorAll('.hex').forEach(e=>e.remove());for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const actor=units.find(p=>p.r===r&&p.c===c),enemy=enemies.find(p=>p.r===r&&p.c===c),cell=document.createElement('button');cell.type='button';cell.className='hex '+(r>=4?'own':r===3?'neutral':'blocked');if(u&&r>=4)cell.classList.add('deploy');if(u&&hexDistance(u,{r,c})<=u.range&&!(u.r===r&&u.c===c))cell.classList.add('inrange');if(actor?.id===selected)cell.classList.add('selected');cell.style.left=((53+c*65+(r%2)*32.5-32)/560*100)+'%';cell.style.top=((73+r*56-37)/560*100)+'%';cell.style.zIndex=String(10+r*2+(actor?.id===selected?1:0));cell.dataset.row=r;cell.dataset.col=c;cell.setAttribute('aria-label','第'+(r+1)+'列第'+(c+1)+'欄，'+(actor?actor.name+' '+actor.job:enemy?enemy.name:r>=4?'可部署空格':'不可部署'));cell.setAttribute('aria-pressed',actor?.id===selected?'true':'false');cell.innerHTML='<span class="tile"></span><span class="coord">'+(r+1)+'·'+(c+1)+'</span>';if(actor||enemy){sprite(cell,actor?.type||0,!!enemy);const lab=document.createElement('span');lab.className='unit-label';lab.textContent=actor?.name||enemy.name;cell.append(lab);const badge=document.createElement('span');badge.className='role-dot'+(enemy?' enemy-marker':'');badge.textContent=enemy?'敵':actor.type===0?'盾':actor.type===1?'劍':'法';cell.append(badge)}cell.onclick=()=>onCell(r,c);board.append(cell)}
roster.replaceChildren();units.forEach(unit=>{const b=document.createElement('button');b.type='button';b.className='roster-unit';b.setAttribute('aria-label','選擇'+unit.name+'，'+unit.job);b.setAttribute('aria-pressed',String(selected===unit.id));sprite(b,unit.type);const text=document.createElement('div');text.innerHTML='<b>'+unit.name+'</b><span class="meta">'+unit.job+' · '+unit.range+'格</span>';b.append(text);const pos=document.createElement('span');pos.className='position';pos.textContent=(unit.r+1)+'列 '+(unit.c+1)+'欄';b.append(pos);b.onclick=()=>select(unit.id);roster.append(b)});
if(u){details.innerHTML='<h2>'+u.name+' <span>'+u.job+'</span></h2><div class="stats"><span>射程 '+u.range+'格</span><span>位置 '+(u.r+1)+'列 '+(u.c+1)+'欄</span></div><p>'+(u.type===0?'盾衛適合站前排，測試前線空間與後排保護位置。':u.type===1?'近戰戰士需要靠近目標，測試切入路線與前排間隔。':'法師適合後排，以3格射程提示測試站位與覆蓋範圍。')+'</p>'}else details.innerHTML='<h2>選擇一位隊員</h2><p>從角色清單或戰場選取，查看部署位置與攻擊射程。</p>';
document.querySelector('#undo').disabled=history.length===0;document.querySelector('#clear').disabled=!selected;paintSprites();if(focusCell)board.querySelector('[data-row="'+focusCell.r+'"][data-col="'+focusCell.c+'"]')?.focus({preventScroll:true});else if(focusRoster)[...roster.children].find(e=>e.getAttribute('aria-label')===focusRoster)?.focus({preventScroll:true})}
document.querySelector('#clear').onclick=()=>{selected=null;say('已取消選取。');render()};document.querySelector('#undo').onclick=()=>{if(!history.length)return;units=history.pop();save();say('已復原上一個站位變更。');render()};document.querySelector('#reset').onclick=()=>{remember();units=structuredClone(defaults);selected=null;save();say('已還原預設陣形，可用「復原一步」返回。');render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;render();say('已取消選取。')}});render();
})();
